import { supabase } from '@/lib/supabase';
import type { CleanDeliverySettings } from '../types/delivery';

export const DEFAULT_CLEAN_DELIVERY_SETTINGS: CleanDeliverySettings = {
  id: 'default',
  is_free_delivery_enabled: true,
  delivery_mode: 'preset_rules',
  flat_delivery_fee: 65,
  preset_zone_radius_km: 5,
  preset_zone1_subtotal: 299,
  preset_zone1_fee: 30,
  preset_zone2_subtotal: 499,
  preset_zone2_fee: 30,
  tier1_max_km: 5,
  tier1_subtotal: 299,
  tier1_fee: 30,
  tier2_max_km: 10,
  tier2_subtotal: 500,
  tier2_fee: 30,
  tier3_subtotal: 699,
  tier3_fee: 30,
};

export async function fetchCleanDeliverySettings(): Promise<CleanDeliverySettings> {
  const { data, error } = await supabase
    .from('delivery_settings')
    .select('*')
    .eq('id', 'default')
    .maybeSingle();

  if (error || !data) {
    return DEFAULT_CLEAN_DELIVERY_SETTINGS;
  }

  return {
    id: data.id || 'default',
    is_free_delivery_enabled: Boolean(data.is_free_delivery_enabled ?? true),
    delivery_mode: data.delivery_mode || 'preset_rules',
    flat_delivery_fee: Number(data.flat_delivery_fee ?? 65),
    preset_zone_radius_km: Number(data.preset_zone_radius_km ?? 5),
    preset_zone1_subtotal: Number(data.preset_zone1_subtotal ?? 299),
    preset_zone1_fee: Number(data.preset_zone1_fee ?? 30),
    preset_zone2_subtotal: Number(data.preset_zone2_subtotal ?? 499),
    preset_zone2_fee: Number(data.preset_zone2_fee ?? 30),
    tier1_max_km: Number(data.tier1_max_km ?? 5),
    tier1_subtotal: Number(data.tier1_subtotal ?? 299),
    tier1_fee: Number(data.tier1_fee ?? 30),
    tier2_max_km: Number(data.tier2_max_km ?? 10),
    tier2_subtotal: Number(data.tier2_subtotal ?? 500),
    tier2_fee: Number(data.tier2_fee ?? 30),
    tier3_subtotal: Number(data.tier3_subtotal ?? 699),
    tier3_fee: Number(data.tier3_fee ?? 30),
  };
}

export async function saveCleanDeliverySettings(input: CleanDeliverySettings): Promise<void> {
  const payload = {
    id: 'default',
    is_free_delivery_enabled: input.is_free_delivery_enabled,
    delivery_mode: input.delivery_mode,
    flat_delivery_fee: input.flat_delivery_fee,
    preset_zone_radius_km: input.preset_zone_radius_km,
    preset_zone1_subtotal: input.preset_zone1_subtotal,
    preset_zone1_fee: input.preset_zone1_fee,
    preset_zone2_subtotal: input.preset_zone2_subtotal,
    preset_zone2_fee: input.preset_zone2_fee,
    tier1_max_km: input.tier1_max_km,
    tier1_subtotal: input.tier1_subtotal,
    tier1_fee: input.tier1_fee,
    tier2_max_km: input.tier2_max_km,
    tier2_subtotal: input.tier2_subtotal,
    tier2_fee: input.tier2_fee,
    tier3_subtotal: input.tier3_subtotal,
    tier3_fee: input.tier3_fee,
    updated_at: new Date().toISOString(),
  };

  const { error } = await supabase
    .from('delivery_settings')
    .upsert(payload);

  if (error) throw error;
}

